#!/usr/bin/env bash
# Fix: Import Licenses from Excel always reported "No valid rows found".
# Generated by gen_deploy_license_import_fix.py - do not hand-edit.
#
# Run this from the repo root on the server.
set -uo pipefail

sec() { echo ""; echo "=== $* ==="; echo "=== $* ===" >&2; }

FAIL=0

sec "0. Confirm repo root"
if [ ! -d "frontend/lib/utils" ]; then
    echo "!!! frontend/lib/utils not found under $(pwd) - run this from the repo root."
    exit 1
fi

sec "1. Pre-flight: verify the touched file is exactly what was confirmed"
if [ ! -f "frontend/lib/utils/license-excel.ts" ]; then
    echo "!!! frontend/lib/utils/license-excel.ts not found - aborting, nothing written yet."
    FAIL=1
else
    h=$(git hash-object "frontend/lib/utils/license-excel.ts")
    if [ "$h" != "f2b2e2ec001da29991c1d95b909f94b8695223e0" ]; then
        echo "!!! frontend/lib/utils/license-excel.ts does not match the expected pre-deploy hash."
        echo "    expected: f2b2e2ec001da29991c1d95b909f94b8695223e0"
        echo "    actual:   $h"
        echo "    This file has changed on the server since it was last verified - do not proceed."
        FAIL=1
    fi
fi

if [ "$FAIL" != "0" ]; then
    echo ""
    echo ">>> Pre-flight checks failed - nothing was written. See messages above."
    exit 1
fi
echo "All pre-flight checks passed."

sec "2. Writing files"
mkdir -p "$(dirname "frontend/lib/utils/license-excel.ts")"
base64 -d > "frontend/lib/utils/license-excel.ts.tmp" <<'B64EOF'

B64EOF
mv "frontend/lib/utils/license-excel.ts.tmp" "frontend/lib/utils/license-excel.ts"
echo "wrote frontend/lib/utils/license-excel.ts"

sec "3. Post-flight: verify the written file matches the expected final hash"
POSTFAIL=0
h=$(git hash-object "frontend/lib/utils/license-excel.ts")
if [ "$h" != "d2abe249654c6573f282d06c1c3bda9d9b056ee1" ]; then
    echo "!!! frontend/lib/utils/license-excel.ts does not match the expected post-deploy hash (expected d2abe249654c6573f282d06c1c3bda9d9b056ee1, got $h)"
    POSTFAIL=1
else
    echo "OK: frontend/lib/utils/license-excel.ts"
fi

if [ "$POSTFAIL" != "0" ]; then
    echo ""
    echo ">>> Post-deploy verification failed - do not restart the frontend; investigate before proceeding."
    exit 1
fi

sec "4. Done"
echo "File written and verified. Next steps:"
echo "  1. git add -A && git commit  (commit this on the server's own checkout)"
echo "  2. docker compose build frontend && docker compose up -d frontend"
echo "  3. Open Licenses -> Import Licenses from Excel, upload a real filled-in file (your own exported-then-filled-in template is perfect), and confirm it now imports successfully instead of saying No valid rows found"
echo "  4. Confirm the imported licenses show the correct Software name and Purchase Batch/PO Number (both were previously silently blanked by this bug)"
echo ">>> DONE"
